// Concatenates supabase/migrations/*.sql (in order) into supabase/setup.sql so a fresh
// project can be set up with ONE paste into the Supabase SQL Editor.
// The migrations remain the source of truth: run `npm run db:bundle` after changing them.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const parts = [
  "-- GENERATED by `npm run db:bundle` from supabase/migrations/*.sql — do not edit by hand.",
  "-- Paste this whole file into the Supabase SQL Editor and run it ONCE on a fresh project.",
  "-- (Already ran the individual migrations? Don't run this again.)",
  "",
  ...files.map((f) => `-- ============================================================\n-- ${f}\n-- ============================================================\n${readFileSync(join(dir, f), "utf8").trim()}\n`),
];

writeFileSync("supabase/setup.sql", parts.join("\n"));
console.log(`Wrote supabase/setup.sql from ${files.length} migrations: ${files.join(", ")}`);
